#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    // Proof that shared_counts_agree invariant is preserved by shared_finish

    // Establish the relationship between pre and post states
    assert(post.shared_pending == pre.shared_pending.remove(r));

    // The birds_eye lets us extract value t from pre.storage
    let t = pre.storage->0;
    assert(post.shared_guard == pre.shared_guard.insert((r, t)));

    // ref_counts is unchanged
    assert forall |r0| 0 <= r0 < post.rc_width implies
        post.ref_counts.index(r0) == pre.ref_counts.index(r0)
    by {};

    // Verify the invariant holds for all r0
    assert forall |r0| 0 <= r0 < post.rc_width implies
        #[trigger] post.ref_counts.index(r0) ==
            post.shared_pending.count(r0) as int +
            Self::filter_r(post.shared_guard, r0).len() as int
    by {
        // By invariant assumption on pre-state
        assert(pre.ref_counts.index(r0) == 
               pre.shared_pending.count(r0) as int +
               Self::filter_r(pre.shared_guard, r0).len() as int);

        if r0 == r {
            // For the modified index r:
            // - shared_pending.count(r) decreased by 1 (from pre to post)
            // - filter_r(shared_guard, r).len() increased by 1 (from pre to post)
            // - ref_counts.index(r) unchanged
            // So the total remains the same

            assert(post.shared_pending.count(r0) == pre.shared_pending.count(r0) - 1);
            assert(Self::filter_r(post.shared_guard, r0).len() == Self::filter_r(pre.shared_guard, r0).len() + 1);
            assert(post.ref_counts.index(r0) == pre.ref_counts.index(r0));

            // Therefore:
            // post.ref_counts[r0] = pre.ref_counts[r0]
            //                     = pre.shared_pending[r0] + Self::filter_r(pre.shared_guard,r0).len
            //                     = (post.shared_pending[r0] + 1) + Self::filter_r(pre.shared_guard,r0).len
            //                     = post.shared_pending[r0] + (Self::filter_r(pre.shared_guard,r0).len + 1)
            //                     = post.shared_pending[r0] + Self::filter_r(post.shared_guard,r0).len
            assert(post.ref_counts.index(r0) == post.shared_pending.count(r0) as int + Self::filter_r(post.shared_guard, r0).len() as int);
        } else {
            // For other indices, nothing changes
            assert(post.shared_pending.count(r0) == pre.shared_pending.count(r0));
            assert(Self::filter_r(post.shared_guard, r0).len() == Self::filter_r(pre.shared_guard, r0).len());
            assert(post.ref_counts.index(r0) == pre.ref_counts.index(r0));

            // So the equation still holds
            assert(post.ref_counts.index(r0) == post.shared_pending.count(r0) as int + Self::filter_r(post.shared_guard, r0).len() as int);
        }
    }
}

