        assert(pre.ref_counts.index(r0) == 
               pre.shared_pending.count(r0) as int +
               Self::filter_r(pre.shared_guard, r0).len() as int);

        if r0 == r {
            // The crucial case - this is the index we modified

            // Key facts (established by the state machine semantics):
            assert(post.shared_pending.count(r0) == pre.shared_pending.count(r0) - 1);
            assert(post.ref_counts.index(r0) == pre.ref_counts.index(r0));

            // The mathematical identity we need to verify:
            // post.ref_counts[r0] = post.shared_pending[r0] + len(filter_r(post.shared_guard, r0))
            // We know:
            //   post.ref_counts[r0] = pre.ref_counts[r0]                              (unchanged)
            //   post.shared_pending[r0] = pre.shared_pending[r0] - 1                  (removed {r0})
